pipe_demolish_btn_center :: proc(view: ^rnd.View) -> rl.Vector2 {
	a := rnd.node_screen(view, FIXTURE_RES_POS)
	b := rnd.node_screen(view, FIXTURE_RT_POS)
	anchor := rl.Vector2{(a.x + b.x) / 2, (a.y + b.y) / 2}
	pop := rnd.popover_rect(view, anchor, rnd.POPOVER_H_PIPE)
	btn := rnd.demolish_button_rect(pop)
	return {btn.x + btn.width / 2, btn.y + btn.height / 2}
}
